import pandas as pd
def _frame():
    return pd.DataFrame({'order': [1, 2, 3], 'region': ['n', 's', 'n'], 'qty': [2, 1, 4], 'price': [1.0, float('nan'), 3.0]})
for _call in (lambda d: revenue_by_region(d), lambda d: big_orders(d, 2), lambda d: missing_counts(d)):
    _df = _frame()
    _before = _df.copy(deep=True)
    _call(_df)
    assert _df.equals(_before), 'none of the functions may change df (missing values included)'

