import pandas as pd


def revenue_by_region(df):
    revenue = (df["qty"] * df["price"].fillna(0)).groupby(df["region"]).sum()
    return revenue.sort_values(ascending=False).to_dict()


def big_orders(df, min_qty):
    return df.loc[df["qty"] >= min_qty, ["order", "qty"]]


def missing_counts(df):
    return {col: int(n) for col, n in df.isna().sum().items()}
